"""Self-contained desktop HTML for Inspect's saved-GT comparison evidence."""

from __future__ import annotations

import html
import json


def render_html(report: dict) -> str:
    data = (
        json.dumps(report, ensure_ascii=False, allow_nan=False)
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
    )
    return TEMPLATE.replace("__TITLE__", html.escape(report["title"])).replace(
        "__DATA__", data
    )


